+function valueIsSuperset(left: unknown, right: unknown): boolean {
+	// strings must only be contained in the new string
+	if (typeof left === 'string' && typeof right === 'string') {
+		return stringContainsParts(right, left);
+	}
+
+	if (Array.isArray(left) || Array.isArray(right)) {
+		if (!Array.isArray(left) || !Array.isArray(right)) return false;
+		if (left.length !== right.length) return false;
+		return left.every((v, i) => valueIsSuperset(v, right[i]));
+	}
+
+	const isPlainObject = (v: unknown): v is Record<string, unknown> =>
+		typeof v === 'object' && v !== null && !(v instanceof Date);
+
+	if (isPlainObject(left) && isPlainObject(right)) {
+		const leftKeys = Object.keys(left);
+		if (leftKeys.length !== Object.keys(right).length) return false;
+		return leftKeys.every(
+			(k) =>
+				Object.prototype.hasOwnProperty.call(right, k) && valueIsSuperset(left[k], right[k]),
+		);
+	}
+
+	// other values must be exactly equal to not be lost data
+	return isEqual(left, right);
+}
